	pmt := ta("Rmz", "Zahlung jeder Periode (negativ, wenn sie geleistet wird).")
	per := ta("Zr", "Nummer der Periode, von 1 bis Zzr.")
	guess := ta("Schätzwert", "Startzins der Berechnung (10 %, wenn nicht angegeben).")
	round := ta("Zahl", "Zu rundende Zahl.")
	digits := ta("Anzahl_Stellen", "Anzahl der Nachkommastellen; negativ für Zehner, Hunderter…")
